#include <set>
#include "osalloc.h"

class vr_billboard;

template <class T>
class instance_bank
{
public:
  struct ref_t
  {
    T* ptr;
  };

  class less_by_ptr : public binary_function<const ref_t*, const ref_t*, bool>
  {
  public:
    bool operator()(const ref_t* a, const ref_t* b) const
    {
      return a->ptr < b->ptr;
    }
  };
};

typedef instance_bank<vr_billboard> billboard_bank_t;
typedef set<billboard_bank_t::ref_t*, billboard_bank_t::less_by_ptr, malloc_alloc>
  billboard_ref_set_t;

pair<billboard_ref_set_t::iterator, bool>
force_insert_unique(billboard_ref_set_t& refs, billboard_bank_t::ref_t* const& ref)
{
  return refs.insert(ref);
}
